{
  "headline": "Granisetron hydrochloride supply at Corvale sites covers 15 to 27 days; the labeled manufacturer OrBion Pharmaceuticals Private Limited has a history of VAI inspections and a recent NAI inspection on 2025-10-27; Breckenridge Pharmaceutical, Inc. is not on FDA's shortage list today but its label names no plant we could place.",
  "headline_cites": ["D1", "D2", "E7", "E3", "E4", "E5", "E6"],
  "sentences": [
    {
      "text": "Corvale East has 204 units on hand at 7.6 units per day, providing 27 days of supply.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General has 135 units on hand at 9.1 units per day, providing 15 days of supply.",
      "cites": ["D2"]
    },
    {
      "text": "The product label for NDC 69452035001 identifies OrBion Pharmaceuticals Private Limited (FEI 3004540907) as the manufacturing plant, with operations including analysis, labeling, manufacture, and pack.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection records for that plant show VAI classifications on 2011-04-07, 2015-06-03, 2019-05-31, and 2023-09-08.",
      "cites": ["E3", "E4", "E5", "E6"]
    },
    {
      "text": "The most recent inspection listed for the plant is an NAI classification dated 2025-10-27.",
      "cites": ["E7"]
    },
    {
      "text": "Breckenridge Pharmaceutical, Inc. is not on FDA's shortage list as of 2026-10-21, but its label does not name a plant we could place.",
      "cites": ["E7"]
    },
    {
      "text": "Check current inventory allocation between sites and verify Breckenridge's manufacturing site before committing to a purchase.",
      "cites": ["D1", "D2", "E7"]
    }
  ]
}
